INSERT INTO workflow_revision_source_rules VALUES(2,'UBL','survey-framework','{"source":"exact-final-approved-framework","quotationRequired":false,"allowedRevision":"configuration-only","commercialChangesAllowed":false,"surveyInputChanges":"return-to-design","retainFrozenRates":true,"retainFinancialHistory":true}',now());
CREATE TABLE framework_configuration_revisions(request_id uuid PRIMARY KEY REFERENCES framework_revision_requests(id),target_framework_id uuid NOT NULL REFERENCES project_framework_versions(id),boq_revision_id uuid NOT NULL REFERENCES boq_revisions(id),snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_framework_configuration_revision BEFORE UPDATE OR DELETE ON framework_configuration_revisions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
